package com.carebridge.backend.partner.controller;import com.carebridge.backend.partner.service.SponsoredApprovalService;import com.carebridge.backend.partner.dto.request.ContentDecisionRequest;import com.carebridge.backend.partner.dto.response.ContentDecisionResponse;import com.carebridge.backend.partner.entity.PartnerContentTargetType;import com.carebridge.backend.common.response.ApiResponse;import com.carebridge.backend.common.util.SecurityUtils;import jakarta.validation.Valid;import java.security.Principal;import java.util.UUID;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/admin/partner-content") @PreAuthorize("hasRole('SYSTEM_ADMIN')") @RequiredArgsConstructor public class SponsoredApprovalController{private final SponsoredApprovalService service;@PostMapping("/{targetType}/{targetId}/decision")public ResponseEntity<ApiResponse<ContentDecisionResponse>> decide(@PathVariable PartnerContentTargetType targetType,@PathVariable UUID targetId,@Valid @RequestBody ContentDecisionRequest request,Principal principal){return ResponseEntity.ok(ApiResponse.success(service.decide(targetType,targetId,request,SecurityUtils.requireCurrentUserId(principal)),"Partner content decision applied successfully"));}}
